/**
 * Web Search Service — 100% Free, No API Key Required
 * Uses DuckDuckGo + SearXNG public instances
 * Supports English and Khmer queries
 */

export interface SearchResult {
  title: string;
  snippet: string;
  url: string;
}

/**
 * Translate Khmer query to English for better search results
 */
function translateQueryToEnglish(query: string): string {
  const translations: Record<string, string> = {
    "តើ": "what is",
    "ជាអ្វី": "what is",
    "នៅឯ": "at",
    "នៅ": "at",
    "ថ្ងៃនេះ": "today",
    "ម្សិលមិញ": "yesterday",
    "សប្តាហ៍នេះ": "this week",
    "ខែនេះ": "this month",
    "ឆ្នាំនេះ": "this year",
    "តម្លៃ": "price",
    "អាកាសធាតុ": "weather",
    "ព័ត៌មាន": "news",
    "លទ្ធផល": "results",
    "កាលវិភាគ": "schedule",
    "ស្វែងរក": "search",
    "ស្រាវជ្រាវ": "research",
    "តើអ្នកណាជា": "who is",
    "តើនរណាជា": "who is",
    "ផ្សារហ៊ុន": "stock market",
    "អត្រាប្តូរប្រាក់": "exchange rate",
    "តម្លៃមាស": "gold price",
    "ពិន្ទុបាល់ទាត់": "football score",
  };

  let translated = query;
  for (const [khmer, english] of Object.entries(translations)) {
    if (translated.includes(khmer)) {
      translated = translated.replace(khmer, english);
    }
  }

  const hasKhmer = /[\u1780-\u17FF\u19E0-\u19FF]/.test(translated);
  if (hasKhmer) {
    return query + " " + translated;
  }

  return translated;
}

/**
 * Search using SearXNG public instances (free, no API key)
 */
async function searchSearXNG(query: string, maxResults: number): Promise<SearchResult[]> {
  // Public SearXNG instances
  const instances = [
    "https://search.sapti.me",
    "https://searx.tiekoetter.com",
    "https://search.bus-hit.me",
    "https://searx.work",
    "https://search.ononoki.org",
  ];

  for (const instance of instances) {
    try {
      const url = `${instance}/search?q=${encodeURIComponent(query)}&format=json&categories=general&language=en`;
      const response = await fetch(url, {
        headers: {
          "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
          "Accept": "application/json",
        },
        signal: AbortSignal.timeout(8000),
      });

      if (!response.ok) continue;

      const data = await response.json();
      const results: SearchResult[] = [];

      if (data.results && Array.isArray(data.results)) {
        for (const item of data.results.slice(0, maxResults)) {
          if (item.title && item.url) {
            results.push({
              title: item.title,
              snippet: item.content || item.snippet || "",
              url: item.url,
            });
          }
        }
      }

      if (results.length > 0) {
        console.log(`[WebSearch] SearXNG (${instance}) returned ${results.length} results`);
        return results;
      }
    } catch (err) {
      console.warn(`[WebSearch] SearXNG ${instance} failed:`, (err as Error).message?.slice(0, 50));
      continue;
    }
  }

  return [];
}

/**
 * Search using DuckDuckGo HTML scraping (free, no API key)
 */
async function searchDuckDuckGo(query: string, maxResults: number): Promise<SearchResult[]> {
  try {
    const results: SearchResult[] = [];

    // Method 1: DuckDuckGo Instant Answer API
    const instantUrl = `https://api.duckduckgo.com/?q=${encodeURIComponent(query)}&format=json&no_html=1&skip_disambig=1`;
    const instantRes = await fetch(instantUrl, {
      headers: { "User-Agent": "Mozilla/5.0" },
      signal: AbortSignal.timeout(8000),
    });

    if (instantRes.ok) {
      const data = await instantRes.json();

      if (data.AbstractText) {
        results.push({
          title: data.Heading || query,
          snippet: data.AbstractText,
          url: data.AbstractURL || `https://duckduckgo.com/?q=${encodeURIComponent(query)}`,
        });
      }

      if (data.RelatedTopics && Array.isArray(data.RelatedTopics)) {
        for (const topic of data.RelatedTopics.slice(0, 4)) {
          if (topic.Text && topic.FirstURL) {
            results.push({
              title: topic.Text.slice(0, 120),
              snippet: topic.Text,
              url: topic.FirstURL,
            });
          }
        }
      }
    }

    // Method 2: DuckDuckGo HTML
    if (results.length < maxResults) {
      try {
        const htmlUrl = `https://html.duckduckgo.com/html/?q=${encodeURIComponent(query)}`;
        const htmlRes = await fetch(htmlUrl, {
          method: "POST",
          headers: {
            "Content-Type": "application/x-www-form-urlencoded",
            "User-Agent": "Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36",
          },
          body: `q=${encodeURIComponent(query)}`,
          signal: AbortSignal.timeout(8000),
        });

        if (htmlRes.ok) {
          const html = await htmlRes.text();

          // Extract results from DDG HTML
          const resultRegex = /<a[^>]+class="result__a"[^>]*href="([^"]*)"[^>]*>([^<]*(?:<[^>]*>[^<]*)*)<\/a>/gi;
          const snippetRegex = /<a[^>]+class="result__snippet"[^>]*>([^<]*(?:<[^>]*>[^<]*)*)<\/a>/gi;

          const links: { url: string; title: string }[] = [];
          const snippets: string[] = [];

          let match;
          while ((match = resultRegex.exec(html)) !== null) {
            let url = match[1];
            // Decode DDG redirect URL
            if (url.includes("uddg=")) {
              const uddgMatch = url.match(/uddg=([^&]+)/);
              if (uddgMatch) url = decodeURIComponent(uddgMatch[1]);
            }
            // Strip HTML tags from title
            const title = match[2].replace(/<[^>]*>/g, "").trim();
            if (title && url) links.push({ url, title });
          }

          while ((match = snippetRegex.exec(html)) !== null) {
            snippets.push(match[1].replace(/<[^>]*>/g, "").trim());
          }

          for (let i = 0; i < Math.min(links.length, maxResults - results.length); i++) {
            const url = links[i].url;
            if (!results.some(r => r.url === url)) {
              results.push({
                title: links[i].title,
                snippet: snippets[i] || "",
                url,
              });
            }
          }
        }
      } catch (htmlErr) {
        console.warn("[WebSearch] DDG HTML error:", (htmlErr as Error).message?.slice(0, 50));
      }
    }

    console.log(`[WebSearch] DuckDuckGo returned ${results.length} results`);
    return results.slice(0, maxResults);
  } catch (err) {
    console.error("[WebSearch] DuckDuckGo error:", err);
    return [];
  }
}

/**
 * Search the web — Multiple free sources, no API key needed
 * Order: SearXNG → DuckDuckGo
 */
export async function searchWeb(query: string, maxResults = 5): Promise<SearchResult[]> {
  const searchQuery = translateQueryToEnglish(query);

  // Try SearXNG first (better results)
  const searxngResults = await searchSearXNG(searchQuery, maxResults);
  if (searxngResults.length >= 2) {
    return searxngResults;
  }

  // Fallback to DuckDuckGo
  console.log("[WebSearch] Trying DuckDuckGo...");
  const ddgResults = await searchDuckDuckGo(searchQuery, maxResults);

  // Merge results if both sources returned something
  if (searxngResults.length > 0 && ddgResults.length > 0) {
    const merged = [...searxngResults];
    for (const r of ddgResults) {
      if (!merged.some(m => m.url === r.url)) {
        merged.push(r);
      }
    }
    return merged.slice(0, maxResults);
  }

  return ddgResults;
}

/**
 * Format search results into a context string for AI
 */
export function formatSearchResults(results: SearchResult[]): string {
  if (results.length === 0) return "";

  let context = "\n\n--- WEB SEARCH RESULTS ---\n";
  context += "The following are real-time search results from the web. Use this information to provide accurate, up-to-date answers.\n\n";

  for (let i = 0; i < results.length; i++) {
    const r = results[i];
    context += `[${i + 1}] ${r.title}\n`;
    context += `    ${r.snippet}\n`;
    context += `    Source: ${r.url}\n\n`;
  }

  context += "--- END OF SEARCH RESULTS ---\n";
  context += "\nIMPORTANT: Use the above search results to answer the user's question. Cite sources using [1], [2], etc. when referencing specific information.\n";

  return context;
}
